def decide(recipient_reputation, round_num, my_history):
    # slower decay from higher initial threshold
    base_threshold = 0.7 - 0.002 * round_num
    base_threshold = max(0.25, base_threshold)

    # Adjust based on own recent cooperation history (using last 20 rounds)
    recent = my_history[-20:] if len(my_history) > 20 else my_history
    if recent:
        coop_count = sum(1 for obs in recent if obs['action'] == 'A')
        coop_ratio = coop_count / len(recent)
    else:
        coop_ratio = 0.5
    # stronger adjustment: if we have been cooperative a lot, lower threshold
    adjustment = 0.3 * (0.5 - coop_ratio)  # range -0.15 to 0.15
    threshold = base_threshold + adjustment
    threshold = max(0.15, min(0.85, threshold))

    # extra caution in first 3 rounds
    if round_num < 3:
        threshold = 0.8

    return recipient_reputation > threshold
